/**
 * Soulbound test rig — build a character, level it through the checkpoints, and assert at each one.
 *
 * The rig itself lives in `scripts/soulbound/rig.mjs` so it can be iterated without a pack rebuild:
 * a macro's body only changes when the world is shut down and the packs are recompiled, while a
 * module script is re-read on F5.
 */
const api = game.modules.get("isaacs-hb-pf2e").api;
const out = await api.rig.run();
const passed = out.total - out.failed.length;
let body = `<p><strong>${passed}/${out.total}</strong> checks passed.</p>`;
if (out.failed.length > 0) {
    body += `<ul>${out.failed.map((f) => `<li>L${f.level} ${f.label}<br /><em>expected ${f.expected}, got ${f.actual}</em></li>`).join("")}</ul>`;
}
for (const problem of out.promptProblems ?? []) body += `<p><strong>Prompt:</strong> ${problem}</p>`;
ChatMessage.create({ content: `<h3>Soulbound test rig</h3>${body}`, whisper: [game.user.id] });
